lib='''def inbounds(grid, i, j):
    """True if cell (i, j) lies inside the grid."""
    return 0 <= i < len(grid) and 0 <= j < len(grid[0])

def cells(grid, value):
    """All positions (i, j) holding the given value."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == value]

def colors(grid):
    """The set of nonzero colors present in the grid."""
    return {v for row in grid for v in row if v != 0}

def solid_rect(grid, color):
    """(top, bottom, left, right) bounds of all cells of the color."""
    pts = cells(grid, color)
    return min(p[0] for p in pts), max(p[0] for p in pts), min(p[1] for p in pts), max(p[1] for p in pts)

def extend_rectangle_around_marks(grid, marks=(1, 8)):
    """The dominant non-background rectangle's rows extend to the grid edge on each horizontal side with no mark in that row, and its columns likewise vertically; marks are kept."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    B = next(k for k in cnt if k not in (0,) + tuple(marks))
    top, bot, lft, rgt = solid_rect(grid, B)
    out = [row[:] for row in grid]
    for i in range(top, bot + 1):
        if not any(grid[i][j] in marks for j in range(lft)):
            out[i][:lft] = [B] * lft
        if not any(grid[i][j] in marks for j in range(rgt + 1, w)):
            out[i][rgt + 1:] = [B] * (w - rgt - 1)
    for j in range(lft, rgt + 1):
        if not any(grid[i][j] in marks for i in range(top)):
            for i in range(top):
                out[i][j] = B
        if not any(grid[i][j] in marks for i in range(bot + 1, h)):
            for i in range(bot + 1, h):
                out[i][j] = B
    return out
